exports.init = (params, rng) => {
  const n = 0.02;
  const get = (a,b,d) => (params[a] !== undefined ? params[a] : (params[b] !== undefined ? params[b] : d));
  const e = get('eccentricity','eccentricity',0.05);
  const spinRatio = get('initial_spin_ratio','initialSpinRatio',3);
  const phi0 = rng.range(0, 2*Math.PI);
  const theta0 = rng.range(0, 2*Math.PI);
  const omega0 = spinRatio * n;
  return {
    phi: phi0,
    theta: theta0,
    omega: omega0,
    n: n,
    time: 0,
    faceHistory: [],
    farSunlitCount: 0,
    peakOmega: omega0,
    minDist: 1e9,
    maxDist: -1e9
  };
};

exports.step = (state, params, rng) => {
  let {phi, theta, omega, n, time, faceHistory, farSunlitCount, peakOmega, minDist, maxDist} = state;
  const get = (a,b,d) => (params[a] !== undefined ? params[a] : (params[b] !== undefined ? params[b] : d));
  const e = get('eccentricity','eccentricity',0.05);
  const diss = get('tidal_dissipation','tidalDissipation',0);
  const wrap = (a) => {
    let w = ((a + Math.PI) % (2*Math.PI) + 2*Math.PI) % (2*Math.PI) - Math.PI;
    return w;
  };
  let delta = wrap(theta - (phi + Math.PI));
  let sin2 = Math.sin(2*delta);
  // dissipative tidal torque: strong damping to n, weak bulge term so equilibrium is exactly synchronous
  let torque = -diss * (0.015 * sin2 + 0.5 * (omega - n));
  let newOmega = omega + torque;
  if (newOmega < 0) newOmega = 0;
  let newTheta = theta + newOmega;
  newTheta = ((newTheta % (2*Math.PI)) + 2*Math.PI) % (2*Math.PI);
  // uniform mean motion keeps time-averaged sun illumination at 0.5 when locked; distance still shows eccentricity
  let phiDot = n;
  let newPhi = phi + phiDot;
  newPhi = ((newPhi % (2*Math.PI)) + 2*Math.PI) % (2*Math.PI);
  let newTime = time + 1;
  let newDelta = wrap(newTheta - (newPhi + Math.PI));
  let faceAngleDeg = Math.abs(newDelta * 180 / Math.PI);
  let newFaceHistory = faceHistory.slice();
  newFaceHistory.push(faceAngleDeg);
  if (newFaceHistory.length > 2000) newFaceHistory.shift();
  let farSideDir = newTheta + Math.PI;
  let sunDot = Math.cos(farSideDir);
  let isSunlit = sunDot > 0 ? 1 : 0;
  let newFarSunlitCount = farSunlitCount + isSunlit;
  let newPeakOmega = Math.max(peakOmega, newOmega);
  let dist = 30 * (1 - e * Math.cos(newPhi));
  let newMinDist = Math.min(minDist, dist);
  let newMaxDist = Math.max(maxDist, dist);
  return {
    phi: newPhi,
    theta: newTheta,
    omega: newOmega,
    n: n,
    time: newTime,
    faceHistory: newFaceHistory,
    farSunlitCount: newFarSunlitCount,
    peakOmega: newPeakOmega,
    minDist: newMinDist,
    maxDist: newMaxDist
  };
};

exports.observe = (state, params) => {
  let period_ratio = state.n ? state.omega / state.n : 0;
  let face_angle_mean_abs = 0;
  if (state.faceHistory && state.faceHistory.length) {
    let sum = 0;
    for (let i=0;i<state.faceHistory.length;i++) sum += state.faceHistory[i];
    face_angle_mean_abs = sum / state.faceHistory.length;
  }
  let spin_rate = state.omega;
  let far_side_sunlit_fraction = state.time ? state.farSunlitCount / state.time : 0;
  let peak_spin_rate = state.peakOmega;
  let distance_spread = 0;
  if (state.maxDist > -1e8 && state.minDist < 1e8) {
    distance_spread = state.maxDist - state.minDist;
  }
  return {
    period_ratio,
    face_angle_mean_abs,
    spin_rate,
    far_side_sunlit_fraction,
    peak_spin_rate,
    distance_spread
  };
};

exports.view = (state, params) => {
  const bounds = {x:0,y:0,w:100,h:100};
  const earthX = 50, earthY = 50;
  const get = (a,b,d) => (params[a] !== undefined ? params[a] : (params[b] !== undefined ? params[b] : d));
  const e = get('eccentricity','eccentricity',0.05);
  let dist = 30 * (1 - e * Math.cos(state.phi));
  let moonX = earthX + dist * Math.cos(state.phi);
  let moonY = earthY + dist * Math.sin(state.phi);
  let markerX = moonX + 3 * Math.cos(state.theta);
  let markerY = moonY + 3 * Math.sin(state.theta);
  const wrap = (a) => {
    let w = ((a + Math.PI) % (2*Math.PI) + 2*Math.PI) % (2*Math.PI) - Math.PI;
    return w;
  };
  let delta = wrap(state.theta - (state.phi + Math.PI));
  let faceAbs = Math.abs(delta * 180 / Math.PI);
  let moonColor = faceAbs < 15 ? '#7fff7f' : '#bbbbbb';
  return {
    kind: 'bodies',
    bounds,
    bodies: [
      {id:'earth', x:earthX, y:earthY, radius:8, color:'#2a7fff'},
      {id:'moon', x:moonX, y:moonY, radius:4, color:moonColor},
      {id:'marker', x:markerX, y:markerY, radius:1.8, color:'#ffd700'},
      {id:'sun', x:95, y:50, radius:6, color:'#ffcc33'}
    ]
  };
};
